(() => {
'use strict';
const D=window.CANDY_DATA, STATIC=document.querySelector('meta[name=app-mode]')?.content==='static';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const image=p=>esc(p||D.characters[0]?.image||'');
const key=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const date=s=>`<span translate="no" data-locale-date="${esc(s)}">${new Date(s).toLocaleDateString(window.CandyI18n.locale)}</span>`;
const money=(v,c='USD')=>`<span translate="no" data-locale-money="${v}" data-currency="${esc(c)}">${new Intl.NumberFormat(window.CandyI18n.locale,{style:'currency',currency:c}).format(v/(10**new Intl.NumberFormat('en',{style:'currency',currency:c}).resolvedOptions().maximumFractionDigits))}</span>`;
let plans=[{id:'annual',name:'12 Months',months:12,amount:4788,currency:'USD',tokens:1200},{id:'quarterly',name:'3 Months',months:3,amount:2697,currency:'USD',tokens:300},{id:'monthly',name:'1 Month',months:1,amount:999,currency:'USD',tokens:100}];
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',discover:'M3 5h18v14H3z M10 9l5 3-5 3z',shorts:'M7 2v20M17 2v20M3 6h18M3 18h18M10 9l5 3-5 3z',chat:'M21 11a9 9 0 0 1-9 9H4l-2 2V11a9 9 0 0 1 19 0Z M7 11h.01M12 11h.01M17 11h.01',collection:'M3 4h18v16H3z M3 15l5-5 4 4 3-3 6 5',create:'m4 20 13-13 3 3L7 23z M5 2v5M2 4h6M16 1v4M14 3h5',myai:'M12 21S2 15 2 8c0-5 7-6 10-1 3-5 10-4 10 1 0 7-10 13-10 13Z',premium:'m3 8 4-5h10l4 5-9 14Z M3 8h18M7 3l5 19 5-19',wallet:'M3 5h16v15H3z M14 10h8v6h-8z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2',library:'M4 3h16v18H4z M7 7h10M7 11h10M7 15h5',admin:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6Z'};
function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.home}"/></svg>`}
let modelEnabled=false,activeChatController=null,billingMode=STATIC?'offline':'unavailable';
let me=null,csrf=null,characters=D.characters,favorites=new Set(),renderId=0,heroIndex=0,search='',category='girls';
let draft={step:0,style:'Realistic',gender:'female',name:'',age:25,description:'',personality:'Friendly',voice:'Not connected',image:D.characters[0]?.image};
let offline={user:null,characters:[],favorites:[],conversations:[],messages:[],orders:[]};try{offline={...offline,...JSON.parse(localStorage.getItem('candy-offline-v2')||'{}')}}catch{}
function persist(){localStorage.setItem('candy-offline-v2',JSON.stringify(offline))}
function requireOffline(){if(!offline.user)throw Error('Please enter the offline demo first')}
async function localApi(url,options={}){
 const method=options.method||'GET',b=options.body||{},u=new URL(url,'http://local');
 if(u.pathname==='/api/me')return {user:offline.user,csrf:'offline',balance:0,subscription:null,modelEnabled:false};
 if(u.pathname==='/api/plans')return {plans,billingMode:'offline',recurring:false};
 if(u.pathname==='/api/characters'&&method==='GET')return {characters:[...D.characters,...offline.characters]};
 if(['/api/auth/login','/api/auth/register'].includes(u.pathname)){offline.user={id:'offline-demo',email:b.email||'demo@local.test',name:b.name||'Local demo',role:'user'};persist();return {user:offline.user,csrf:'offline'}}
 if(u.pathname==='/api/auth/logout'){offline.user=null;persist();return {ok:true}}
 if(['/api/auth/forgot','/api/auth/reset'].includes(u.pathname))throw Error('The offline demo has no stored passwords. Password recovery is available only on the MVP server with email configured.');
 requireOffline();
 if(u.pathname==='/api/me/export')return offline;
 if(u.pathname==='/api/auth/password')throw Error('Offline preview has no password authentication. Use the MVP server for account security.');
 if(u.pathname==='/api/characters'&&method==='POST'){const character={...b,id:key(),owner_id:offline.user.id,settings:{personality:b.personality},created:new Date().toISOString()};offline.characters.push(character);persist();return {character}}
 if(u.pathname.startsWith('/api/characters/')&&method==='DELETE'){const id=u.pathname.split('/').pop();offline.characters=offline.characters.filter(c=>c.id!==id);persist();return {ok:true}}
 if(u.pathname==='/api/favorites')return {characters:[...D.characters,...offline.characters].filter(c=>offline.favorites.includes(c.id))};
 if(u.pathname.startsWith('/api/favorites/')){const id=u.pathname.split('/').pop();offline.favorites=offline.favorites.filter(x=>x!==id);if(method==='PUT')offline.favorites.push(id);persist();return {ok:true}}
 if(u.pathname==='/api/conversations'&&method==='GET')return {conversations:offline.conversations.map(c=>{const ch=characters.find(x=>x.id===c.character_id);return {...c,character_name:ch?.name,image:ch?.image}})};
 if(u.pathname==='/api/conversations'&&method==='POST'){let conversation=offline.conversations.find(c=>c.character_id===b.characterId);if(!conversation){const c=characters.find(c=>c.id===b.characterId);conversation={id:key(),user_id:offline.user.id,character_id:c.id,title:c.name,created:new Date().toISOString(),updated:new Date().toISOString()};offline.conversations.push(conversation);persist()}return {conversation}}
 if(u.pathname.startsWith('/api/conversations/')){const cid=u.pathname.split('/')[3],conversation=offline.conversations.find(c=>c.id===cid);if(!conversation)throw Error('Conversation not found');if(method==='DELETE'){offline.conversations=offline.conversations.filter(c=>c.id!==cid);offline.messages=offline.messages.filter(m=>m.conversation_id!==cid);persist();return {ok:true}}if(method==='POST'){const message={id:key(),conversation_id:cid,role:'user',content:b.content,created:new Date().toISOString()};offline.messages.push(message);persist();return {message,modelEnabled:false}}return {conversation,messages:offline.messages.filter(m=>m.conversation_id===cid),character:characters.find(c=>c.id===conversation.character_id),modelEnabled:false}}
 if(u.pathname==='/api/orders'&&method==='GET')return {orders:offline.orders};
 if(u.pathname==='/api/orders'&&method==='POST'){const p=plans.find(p=>p.id===b.plan);const order={id:key(),plan:p.id,amount:p.amount,currency:p.currency,status:'pending',created:new Date().toISOString()};offline.orders.push(order);persist();return {order,notice:'Offline demonstration order only. No payment was collected.'}}
 if(/\/api\/orders\/[^/]+\/cancel/.test(u.pathname)){offline.orders.find(o=>o.id===u.pathname.split('/')[3]).status='cancelled';persist();return {ok:true}}
 if(u.pathname==='/api/wallet')return {balance:0,ledger:[]};
 if(u.pathname==='/api/subscription/cancel')return {ok:true};
 if(u.pathname==='/api/generate')throw Error('Model API is not connected. No credits have been deducted.');
 throw Error('This action requires the MVP server.');
}
async function api(url,options={}){if(STATIC)return localApi(url,options);const headers={'Content-Type':'application/json',...options.headers};if(csrf)headers['X-CSRF-Token']=csrf;const response=await fetch(url,{...options,headers,credentials:'same-origin',body:options.body?JSON.stringify(options.body):undefined});const data=await response.json();if(!response.ok)throw Object.assign(Error(data.error||'Request failed'),{status:response.status});if(data.csrf)csrf=data.csrf;return data}
async function refresh(){const result=await api('/api/me');me=result.user;csrf=result.csrf;modelEnabled=!!result.modelEnabled;const productData=await api('/api/plans');billingMode=productData.billingMode;plans=productData.plans;const c=await api('/api/characters');characters=c.characters;favorites=new Set(me?(await api('/api/favorites')).characters.map(c=>c.id):[]);return result}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.classList.remove('show'),4000)}
function modal(title,content){const dialog=$('#modal');dialog.innerHTML=`<button class="close" data-action="close-modal" aria-label="Close">×</button><h2>${esc(title)}</h2>${content}`;dialog.showModal();wireMemory()}
function route(){const aliases={'/ai-anime':'explore/anime','/ai-boyfriend':'explore/guys','/ai-girlfriend':'explore/girls','/home/discover':'discover','/candy-shorts':'shorts','/characters/new2':'create','/characters/new4':'create','/characters/new':'create','/characters':'my-ai','/collection':'collection','/conversations/none':'chat','/subscriptions':'premium','/users/sign_in':'login','/users/sign_up':'register','/legal-information':'legal','/affiliate-program':'affiliate'};const c=characters.find(c=>c.route===location.pathname);const raw=location.hash.slice(1)||aliases[location.pathname]||(c?'profile/'+c.id:'home');return raw.split('/').map(decodeURIComponent)}
function go(s){if(location.hash==='#'+s)render();else location.hash=s}
function needUser(){if(me)return true;go('login');return false}
function shell(page,content){const nav=[['home','Home','home'],['discover','Discover','discover'],['shorts','Shorts','shorts'],['chat','Chat','chat'],['collection','Collection','collection'],['create','Create Character','create'],['my-ai','My AI','myai'],['library','Media Library','library'],['tokens','Token store','wallet'],['premium','Premium','premium']];$('#app').innerHTML=`<header class="header"><button class="menu-button" data-action="menu" aria-label="Toggle navigation">☰</button><a class="brand" href="#home">candy<span>.ai</span></a><nav class="header-tabs" aria-label="Categories">${[['girls','♀ Girls'],['anime','◎ Anime'],['guys','♂ Guys']].map(([c,t])=>`<a href="#explore/${c}" class="${category===c&&['home','explore'].includes(page)?'active':''}">${t}</a>`).join('')}</nav><form class="header-search" id="header-search"><span>⌕</span><input aria-label="Search characters" placeholder="Search characters, shorts, creators…" name="query"></form><div class="header-right"><select id="language-select" class="language-select" aria-label="Language / 语言" translate="no"><option value="zh-CN">简体中文</option><option value="en">English</option></select><a href="#premium" class="premium-pill">Premium</a><a href="#${me?'settings':'login'}" class="avatar" aria-label="${me?'Account settings':'Sign in'}">${me?esc(me.name.slice(0,1).toUpperCase()):'♙'}</a></div></header><aside class="sidebar">${nav.map(([r,t,i])=>`<a class="navlink ${page===r?'active':''} ${r==='premium'?'premium':''}" href="#${r}">${icon(i)}<span class="navlabel">${t}</span></a>`).join('')}<div class="sidebar-bottom"><a href="#wallet" class="navlink">${icon('wallet')}<span class="navlabel">Tokens & orders</span></a><a href="#settings" class="navlink">${icon('settings')}<span class="navlabel">${me?'Settings':'Sign in'}</span></a>${me?.role==='admin'?`<a href="/admin/" class="navlink">${icon('admin')}<span class="navlabel">Administration</span></a>`:''}<div class="sidebar-note"><a href="#legal">Legal Terms</a> · <a href="#help">Help Center</a><br>${modelEnabled?'Non-commercial preview · AI chat enabled':'Non-commercial preview · AI not connected'}</div></div></aside><main class="main">${STATIC?'<div class="offline-ribbon">Offline static preview · data stays in this browser · no real account or payment</div>':''}<div class="content">${content}${!['chat','login','register','create'].includes(page)?footer():''}</div></main><nav class="mobile-nav" aria-label="Mobile navigation">${[['shorts','Shorts','shorts'],['discover','Discover','discover'],['create','Create','create'],['explore/girls','Search','home'],['chat','Chat','chat']].map(([r,t,i])=>`<a href="#${r}" class="${page===r?'active':''}">${icon(i)}${t}</a>`).join('')}</nav>`;document.body.classList.remove('mobile-menu');wire();window.CandyI18n.apply();}
function footer(){return `<footer class="footer"><div><a class="brand" href="#home">candy<span>.ai</span></a><span class="brand-note">${modelEnabled?'Independent non-commercial replica · AI chat enabled':'Independent non-commercial replica · model API disabled'}</span></div><div><a href="#legal">Terms & privacy</a><a href="#help">Help center</a><a href="#affiliate">Affiliate</a><a href="#library">Local media</a></div></footer>`}
function card(c){return `<a href="#profile/${encodeURIComponent(c.id)}" class="card" data-character="${esc(c.id)}"><img src="${image(c.image)}" alt="${esc(c.name)}" loading="lazy">${c.video?`<video src="${image(c.video)}" poster="${image(c.image)}" muted loop playsinline preload="none"></video>`:''}<span class="card-badge">${c.owner_id?'MY AI':c.style==='Anime'?'ANIME':'FEATURED'}</span><button class="card-save" data-action="favorite" data-id="${esc(c.id)}" aria-label="${favorites.has(c.id)?'Remove from':'Add to'} collection">${favorites.has(c.id)?'♥':'♡'}</button><div class="card-info"><h3><span translate="no">${esc(c.name)}</span> <small>${esc(c.age)}</small></h3><small>${esc(c.style)}</small></div></a>`}
function grid(list){return list.length?`<div class="cards" id="character-grid">${list.map(card).join('')}</div>`:empty('No characters yet','Create a character or browse the collection.','create','Create Character')}
function empty(title,body,target='',label=''){return `<div class="empty">${icon('myai')}<h2>${esc(title)}</h2><p>${esc(body)}</p>${target?`<a href="#${target}" class="btn">${esc(label)}</a>`:''}</div>`}
function filtered(){return characters.filter(c=>!c.owner_id&&(category==='anime'?c.style==='Anime':category==='guys'?c.gender==='male':c.gender==='female'&&c.style!=='Anime')).filter(c=>(c.name+' '+(c.tags||'')).toLowerCase().includes(search.toLowerCase()))}
function toolbar(){return `<div class="toolbar"><input type="search" id="character-search" aria-label="Search characters" placeholder="⌕  Search" value="${esc(search)}">${[['girls','Girls'],['anime','Anime'],['guys','Guys']].map(([c,t])=>`<a class="chip ${category===c?'active':''}" href="#explore/${c}">${t}</a>`).join('')}<button class="chip" data-action="sort">Sort by name</button></div>`}
function hero(){const s=D.slides[heroIndex]||D.slides[0];return `<section class="hero" aria-label="Featured promotions"><img class="hero-image" src="${image(s.image)}" alt="Featured character banner"><div class="hero-content">${s.wordmark?`<img class="hero-wordmark" src="${image(s.wordmark)}" alt="${esc(s.title)}">`:''}<p>${esc(s.subtitle)}</p><a href="#discover" class="btn">Explore Now</a></div><button class="hero-arrow prev" data-action="hero-prev" aria-label="Previous banner">‹</button><button class="hero-arrow next" data-action="hero-next" aria-label="Next banner">›</button><div class="hero-dots">${D.slides.map((s,i)=>`<button class="${heroIndex===i?'active':''}" data-action="hero-dot" data-index="${i}" aria-label="Banner ${i+1}"></button>`).join('')}</div></section>`}
function home(){return `${hero()}<section class="explore-heading"><h2><span class="pink">Explore</span> Featured Characters</h2><p class="subtitle">Chat, call and create with your AI companion</p>${toolbar()}${grid(filtered().slice(0,12))}<p style="margin-top:18px"><a class="pink" href="#explore/girls">View all characters</a></p></section><section class="section"><div class="section-heading"><h2><span class="pink">Discover</span> Video Previews</h2><a href="#shorts">View all</a></div>${videoGrid(D.videos.slice(0,4))}</section><section class="section"><h2>Your next character, your imagination</h2><div class="panel row space-between"><p class="muted">Choose a style, personalize a character, and build your collection.</p><a class="btn" href="#create">Create Character</a></div></section><section class="section"><h2>Candy AI <span class="pink">FAQ</span></h2>${faq()}</section>`}
function faq(){return [['What is included in this version?','You can browse local characters and previews, create a profile, save favorites, and store conversations.'],['Are AI replies connected?',modelEnabled?'AI text replies are enabled. Image, voice and video generation are not connected.':'Not yet. Your messages are saved, but this version does not generate replies, images, voice, or video.'],['Are the videos stored locally?','Yes. The included public preview videos, images, icons and fonts are served from the local asset directory.'],['Will selecting a plan charge me?','No payment is collected by this MVP itself. An order remains pending until an operator confirms settlement or a configured billing adapter sends a verified event.'],['Is this the original Candy AI website?','No. This is a non-commercial replica and MVP implementation. It is not operated by the source website.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}
function videoGrid(videos){return `<div class="video-grid">${videos.map(v=>`<article class="video-tile"><video controls playsinline preload="none" poster="${image(v.poster)}" src="${image(v.src)}" aria-label="${esc(v.title)}"></video><div class="video-caption"><h3>${esc(v.title)}</h3><a href="${image(v.src)}" download>Save MP4</a></div></article>`).join('')}</div>`}
function profile(c){return `<div class="profile-layout"><div><img class="profile-photo" src="${image(c.image)}" alt="${esc(c.name)}"></div><div class="profile-details"><span class="pink">${c.owner_id?'YOUR CHARACTER':'FEATURED CHARACTER'}</span><h1><span translate="no">${esc(c.name)}</span> <span class="muted">${esc(c.age)}</span></h1><div class="tags"><span class="tag">${esc(c.style)}</span><span class="tag">${esc(c.settings?.personality||'Companion')}</span></div><p class="muted"><span translate="no">${esc(c.description)}</span></p><div class="row"><button class="btn" data-action="start-chat" data-id="${esc(c.id)}">${icon('chat')} Start conversation</button><button class="btn secondary" data-action="favorite" data-id="${esc(c.id)}">${favorites.has(c.id)?'♥ Saved':'♡ Save'}</button></div><div class="notice">${modelEnabled?'AI chat is enabled. Messages and replies are saved.':'AI responses are not connected. Conversations can be created and messages saved.'}</div>${c.video?`<h3>Public video preview</h3><video class="profile-preview" controls playsinline preload="metadata" poster="${image(c.image)}" src="${image(c.video)}"></video><p><a href="${image(c.video)}" download class="pink tiny">Download local MP4</a></p>`:''}${!STATIC?`<button class="btn secondary small" data-action="report-message" data-type="character" data-id="${esc(c.id)}">Report content</button>`:''}${c.owner_id?`<button class="btn danger small" data-action="delete-character" data-id="${esc(c.id)}">Delete this character</button>`:''}</div></div>`}
function auth(register){return `<div class="auth panel"><a class="brand" href="#home">candy<span>.ai</span></a><h1>${register?'Create your account':'Welcome back'}</h1><div class="tabs"><a href="#login" class="${!register?'active':''}">Log in</a><a href="#register" class="${register?'active':''}">Sign up</a></div>${STATIC?'<div class="notice">This is an offline demo. No real account is created and no password is stored.</div>':''}<form id="auth-form" class="stack" data-register="${register}">${register?'<label class="form-field">Name<input name="name" autocomplete="nickname" required maxlength="60"></label>':''}<label class="form-field">Email<input type="email" name="email" autocomplete="email" required></label><label class="form-field">Password<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="${STATIC?'1':'12'}" maxlength="128" required><small>${STATIC?'Use any demo value; it will not be saved.':'At least 12 characters.'}</small></label>${register?'<label class="checkline"><input type="checkbox" name="adult" required><span>I am at least 18 and agree to the <a class="pink" href="#legal">terms and privacy notice</a>.</span></label>':''}<p class="form-error" role="alert"></p><button class="btn wide" type="submit">${STATIC?'Enter offline demo':register?'Create account':'Log in'}</button></form><p class="muted tiny" style="margin-top:20px">${STATIC?'Browser-local demo data is separate from MVP accounts.':'Need account recovery? Contact the deployment operator. Email recovery is not configured in this build.'}</p></div>`}
function create(){const styleCharacters=characters.filter(c=>!c.owner_id&&c.style===draft.style&&c.gender===draft.gender);return `<div class="wizard"><h1>Create my AI ${draft.gender==='male'?'Guy':'Girl'}</h1><p class="subtitle">Make a character that is uniquely yours</p><div class="stepper">${[0,1,2,3].map(i=>`<span class="${i<=draft.step?'active':''}"></span>`).join('')}</div>${draft.step===0?`<div class="row" style="justify-content:center"><button class="chip ${draft.gender==='female'?'active':''}" data-action="choose-gender" data-value="female">♀ Girls</button><button class="chip ${draft.gender==='male'?'active':''}" data-action="choose-gender" data-value="male">♂ Guys</button></div><div class="style-options">${['Realistic','Anime'].map(style=>{const c=characters.find(c=>c.style===style&&c.gender===draft.gender)||characters.find(c=>c.style===style);return `<button class="style-choice ${draft.style===style?'selected':''}" data-action="choose-style" data-value="${style}"><img src="${image(c?.image)}" alt="${style} character style"><span>${style}</span></button>`}).join('')}</div>`:draft.step===1?`<div class="panel stack"><h2>Appearance</h2><p class="muted">Choose a portrait from the local library. Image generation will be connected later.</p><div class="portrait-options">${(styleCharacters.length?styleCharacters:characters.filter(c=>!c.owner_id)).slice(0,24).map(c=>`<button class="${draft.image===c.image?'selected':''}" data-action="choose-image" data-value="${image(c.image)}" aria-label="Choose ${esc(c.name)} portrait"><img src="${image(c.image)}" alt="${esc(c.name)}"></button>`).join('')}</div><label class="form-field">Age<input type="number" id="draft-age" min="18" max="100" value="${draft.age}"></label></div>`:draft.step===2?`<form id="character-details" class="panel stack"><h2>Personality</h2><label class="form-field">Name<input id="draft-name" name="name" maxlength="60" required placeholder="Give your character a name" value="${esc(draft.name)}"></label><label class="form-field">Personality<select id="draft-personality">${['Friendly','Creative','Thoughtful','Adventurous','Playful','Calm'].map(p=>`<option value="${p}" ${draft.personality===p?'selected':''}>${p}</option>`).join('')}</select></label><label class="form-field">About your character<textarea id="draft-description" maxlength="1000" placeholder="Interests, background and conversation style">${esc(draft.description)}</textarea></label><div class="notice">Voice generation is not connected in this version.</div></form>`:`<div class="profile-layout"><img class="profile-photo" src="${image(draft.image)}" alt="Character preview"><div class="profile-details"><h2><span translate="no">${esc(draft.name)}</span></h2><div class="tags"><span class="tag">${draft.style}</span><span class="tag">${draft.age} years</span><span class="tag">${esc(draft.personality)}</span></div><p class="muted">${esc(draft.description||'Your new companion.')}</p><div class="notice">Your character will be private to your account. The selected portrait comes from the existing local library.</div></div></div>`}<div class="wizard-actions">${draft.step>0?'<button class="btn secondary" data-action="wizard-back">Back</button>':''}<button class="btn" data-action="${draft.step===3?'save-character':'wizard-next'}">${draft.step===3?'Create Character':'Next'}</button></div></div>`}
async function tokenStore(){const data=STATIC?{rules:[]}:await api('/api/pricing/actions');return `<h1>Token store</h1>${premium(true)}${plans.some(p=>p.kind==='tokens')?'':'<p class="notice">No token packs are currently on sale.</p>'}<section class="panel section"><h2>Token consumption rules</h2><p>Generation services are not connected. No generation charges are currently collected.</p><div class="toolbar">${data.rules.map(r=>`<button class="btn secondary" disabled><span>${({image:'Image generation',voice_msg:'Voice message',avatar:'Avatar generation'})[r.action]}</span> · ${r.cost} <span>Tokens</span></button>`).join('')}</div></section>`}
function premium(tokenOnly=false){return `${billingMode==='unavailable'?'<div class="notice">Payments are not configured. Free chat is available; paid subscriptions are not yet on sale.</div>':''}<h1>Plans and pricing</h1><p class="subtitle">Choose membership or additional tokens. Prices apply to this purchase only.</p><div class="plans">${plans.filter(p=>!tokenOnly||p.kind==='tokens').map(p=>`<article class="plan ${p.recommended?'featured':''}"><div class="deal">${p.kind==='tokens'?'Token pack':'Subscription'}${p.recommended?' · Recommended':''}</div><h2 translate="no">${esc(p.name)}</h2><div class="price">${money(p.amount,p.currency)}</div><p>${p.kind==='tokens'?'Token pack':`${p.cycleCount||p.months} ${p.cycleUnit||'month'}`} · ${p.tokens} tokens</p><p translate="no">${esc(p.benefits||'')}</p><button class="btn wide" data-action="checkout" data-plan="${p.id}" ${billingMode==='unavailable'?'disabled':''}>${billingMode==='unavailable'?'Payment unavailable':'Get Started'}</button></article>`).join('')}</div><p class="notice">No recurring payment is automatically collected. Token packs do not include membership.</p>`}

function orderTable(orders,admin=false){return orders.length?`<div class="table-wrap"><table><thead><tr><th>Order</th>${admin?'<th>Customer</th>':''}<th>Plan</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${esc(o.id.slice(0,10))}<br><span class="muted">${date(o.created)}</span></td>${admin?`<td><span translate="no">${esc(o.email)}</span></td>`:''}<td>${esc(o.plan)}</td><td>${money(o.amount,o.currency)}</td><td><span class="status ${esc(o.status)}">${esc(o.status)}</span></td><td>${o.status==='pending'?`<button class="btn secondary small" data-action="${admin?'settle-order':'cancel-order'}" data-id="${esc(o.id)}">${admin?'Confirm settlement':'Cancel'}</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No orders yet.</p>'}
async function wallet(){const [wallet,orders,account]=await Promise.all([api('/api/wallet'),api('/api/orders'),api('/api/me')]);return `<h1>Tokens & orders</h1><div class="grid-two"><div class="panel"><span class="muted">Available tokens</span><div class="price">${wallet.available??wallet.balance}</div><p><span>Reserved tokens</span>: ${wallet.held||0}</p><p class="muted">Text chat uses your free trial or membership, not your token balance.</p><a href="#tokens" class="btn">Token store</a></div><div class="panel"><h2>Membership</h2><p>${account.subscription?`${esc(account.subscription.plan)} · ${esc(account.subscription.status)}<br>Access until ${date(account.subscription.expires)}`:'No active membership'}</p>${account.subscription?'<button class="btn secondary" data-action="cancel-subscription">Disable renewal</button>':'<p class="muted">Pending orders do not activate membership.</p>'}</div></div><section class="section panel"><h2>Orders</h2>${orderTable(orders.orders)}</section><section class="section panel"><h2>Token history</h2>${wallet.ledger.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Change</th><th>Reason</th></tr></thead><tbody>${wallet.ledger.map(l=>`<tr><td>${date(l.created)}</td><td>${l.delta>0?'+':''}${l.delta}</td><td>${l.reason==='Subscription allocation'?'Subscription allocation':`<span translate="no">${esc(l.reason)}</span>`}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No token transactions.</p>'}</section>`}
async function chat(cid){const list=(await api('/api/conversations')).conversations;let data=cid?await api('/api/conversations/'+encodeURIComponent(cid)):null;return `<div class="chat-layout ${data?'has-conversation':''}"><aside class="chat-list"><div class="section-heading"><h2>Chats</h2><a href="#explore/girls">New chat</a></div>${list.length?list.map(c=>`<a class="chat-person ${c.id===cid?'active':''}" href="#chat/${c.id}"><img src="${image(c.image)}" alt=""><div><strong><span translate="no">${esc(c.character_name)}</span></strong><small>Saved conversation</small></div></a>`).join(''):'<p class="muted">Your conversations will appear here.</p><a class="btn small" href="#explore/girls">Explore characters</a>'}</aside><section class="chat-window">${data?`<header class="chat-header"><a href="#chat" class="pink" aria-label="Back to chats">‹</a><img src="${image(data.character.image)}" alt=""><div><strong><span translate="no">${esc(data.character.name)}</span></strong><small>Conversation saved locally on the server</small></div><button class="btn secondary small" data-action="delete-chat" data-id="${cid}">Delete</button></header><div class="notice">${data.modelEnabled?'AI replies use OpenAI. Recent messages, character details and enabled memory are sent to OpenAI. Successful free replies count toward your trial; members have unlimited text chat.':'Model API is not connected. Messages are saved; no AI reply or credit charge is generated.'}</div>${STATIC?'':`<div id="chat-access" class="notice">${accessText(data.access)}</div>`}${!STATIC&&data.relationshipMemory?`<div id="character-memory" data-character="${esc(data.character.id)}" data-name="${esc(data.character.name)}">${characterMemoryCard(data.relationshipMemory,data.character.name)}</div>`:''}${!STATIC&&data.relationship?`<div id="relationship-card" data-character="${esc(data.character.id)}">${relationshipCard(data.relationship)}</div>`:''}<div class="messages" id="messages">${data.messages.length?data.messages.map(m=>message(m)+failureNotice(data.failures?.find(f=>f.message_id===m.id))).join(''):'<p class="chat-empty">Start your conversation.<br>Your messages will stay here.</p>'}</div><form id="message-form" class="composer" data-id="${cid}"><textarea name="content" placeholder="Write a message…" aria-label="Message" maxlength="4000" required></textarea><button class="btn" type="submit">Send</button></form>`:'<div class="chat-empty"><h2>Your conversations</h2><p>Select a character to get started.</p><a class="btn" href="#explore/girls">Explore characters</a></div>'}</section></div>`}
function failureNotice(f){return f?`<div class="notice" role="alert"><p>${esc(f.error)}</p><button class="btn secondary small" data-action="retry-reply" data-message-id="${esc(f.message_id)}" data-content="${esc(f.content)}">Retry reply</button></div>`:''}
function message(m){return `<div data-message-id="${esc(m.id)}" class="bubble ${m.role==='assistant'?'assistant':'user'}"><span translate="no">${esc(m.content)}</span><small><span translate="no" data-locale-date="${esc(m.created)}" data-date-kind="time">${new Date(m.created).toLocaleTimeString(window.CandyI18n.locale,{hour:'2-digit',minute:'2-digit'})}</span>${!STATIC&&m.role==='assistant'?`<button class="btn secondary small" data-action="report-message" data-id="${esc(m.id)}">Report content</button>`:''}</small></div>`}
function recovery(token){return `<div class="auth panel"><h1>${token?'Set a new password':'Reset your password'}</h1><p class="muted">${token?'Reset links expire after 15 minutes and can only be used once.':'Enter your account email to request a reset link.'}</p><form id="recovery-form" class="stack" data-token="${esc(token||'')}">${token?'<label class="form-field">New password<input type="password" name="password" minlength="12" maxlength="128" autocomplete="new-password" required></label>':'<label class="form-field">Email<input type="email" name="email" autocomplete="email" required></label>'}<p class="form-error" role="alert"></p><button class="btn">${token?'Reset password':'Send reset link'}</button></form><p style="margin-top:20px"><a class="pink" href="#login">Back to login</a></p></div>`}
async function settings(){const spending=STATIC?null:await api('/api/me/settings');const memoryData=STATIC?null:await api('/api/me/memory');return `<h1>Account settings</h1>${spending?spendingPanel(spending):''}${memoryData?memoryPanel(memoryData):''}<div class="grid-two"><form id="profile-form" class="panel stack"><h2>Profile</h2><label class="form-field">Name<input name="name" maxlength="60" value="${esc(me.name)}" required></label><label class="form-field">Email<input value="${esc(me.email)}" disabled></label><p class="form-error" role="alert"></p><button class="btn">Save changes</button></form><form id="password-form" class="panel stack"><h2>Security</h2><label class="form-field">Current password<input name="currentPassword" type="password" autocomplete="current-password" required></label><label class="form-field">New password<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><p class="form-error" role="alert"></p><button class="btn secondary">Change password</button></form></div><section class="section panel"><h2>Your data</h2><p class="muted">Export your profile, characters, conversations, messages and billing records.</p><div class="row"><button class="btn secondary" data-action="export">Export my data</button><button class="btn danger" data-action="logout">Log out</button>${STATIC?'':'<button class="btn danger" data-action="delete-account">Delete account</button>'}</div></section>`}
const adminUI=window.createAdminUI({api,esc,money,date,modal,toast,render,refresh,operationsPanel});
async function admin(section){if(me.role!=='admin')return empty('Administrator access required','This area is restricted to the deployment operator.');return adminUI.page(section)}

function accessText(a){if(!a)return '';if(!a.chatEnabled)return 'Companion chat is currently unavailable.';if(a.unlimited)return 'Unlimited text chat';return `${a.remaining} / ${a.limit} free replies remaining`}
function showPaywall(){modal('Free trial completed','<p>You have used your free replies. Subscribe for unlimited text chat. Unpaid orders do not unlock access.</p><a class="btn" href="#premium" data-action="close-modal">View subscription plans</a>');const link=$('#modal a');link.addEventListener('click',()=>{go('premium')})}
async function sendChat(e){
 e.preventDefault();const form=e.currentTarget,input=$('textarea',form),button=$('button',form),content=input.value.trim();if(!content||button.disabled)return;
 if(form.dataset.requestContent!==content){delete form.dataset.requestKey;delete form.dataset.retryMessageId}form.dataset.requestContent=content;
 const box=$('#messages'),requestKey=form.dataset.requestKey||key(),retryMessageId=form.dataset.retryMessageId;
 form.dataset.requestKey=requestKey;button.disabled=true;button.textContent=modelEnabled?'Generating reply…':'Saving…';
 let bubble=null,saved=false,finished=false,lastSaved=null;
 const setAccess=a=>{const el=$('#chat-access');if(el)el.textContent=accessText(a)};
 const savedMessage=m=>{if(!m)return;lastSaved=m;if(!saved)input.value='';saved=true;delete form.dataset.requestKey;delete form.dataset.retryMessageId;$('.chat-empty',box)?.remove();if(!box.querySelector(`[data-message-id="${m.id}"]`)){box.insertAdjacentHTML('beforeend',message(m));box.lastElementChild.dataset.messageId=m.id}};
 const failReply=(error,m)=>{bubble?.remove();bubble=null;const el=document.createElement('div');el.className='notice';el.setAttribute('role','alert');const label=document.createElement('p');label.textContent=error;el.append(label);if(m){const retry=document.createElement('button');retry.className='btn secondary small';retry.dataset.action='retry-reply';retry.dataset.messageId=m.id;retry.dataset.content=m.content;retry.textContent='Retry reply';el.append(retry)}box.append(el)};
 const handle=(type,data)=>{
  if(data.relationship)updateRelationshipCard(data.relationship);
  if(type==='message'){savedMessage(data.message);setAccess(data.access)}
  if(type==='delta'){if(!bubble){bubble=document.createElement('div');bubble.className='bubble assistant';bubble.setAttribute('translate','no');box.append(bubble)}bubble.textContent+=data.delta}
  if(type==='reply'){$$('[data-action=retry-reply]',box).forEach(b=>{if(b.dataset.messageId===lastSaved?.id)b.parentElement.remove()});bubble?.remove();bubble=null;if(data.assistantMessage){box.insertAdjacentHTML('beforeend',message(data.assistantMessage));box.lastElementChild.dataset.messageId=data.assistantMessage.id}setAccess(data.access)}
  if(type==='done'||type==='error'){finished=true;savedMessage(data.message);if(data.replyError)failReply(data.replyError,data.message);if(data.memoryWarning)toast(data.memoryWarning);if(data.relationshipMemory)updateMemoryCard(data.relationshipMemory);setAccess(data.access)}
  box.scrollTop=box.scrollHeight;
 };
 try{
  if(STATIC){const data=await api('/api/conversations/'+form.dataset.id+'/messages',{method:'POST',body:{content}});savedMessage(data.message);finished=true;return}
  activeChatController=new AbortController();
  const response=await fetch('/api/conversations/'+form.dataset.id+'/messages',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,'Idempotency-Key':requestKey,Accept:'text/event-stream'},body:JSON.stringify({content,...(retryMessageId?{retryMessageId}:{})}),signal:activeChatController.signal});
  if(!response.ok){const data=await response.json();if(response.status===402){delete form.dataset.requestKey;showPaywall();return}throw Error(data.error||'Request failed')}
  if(!(response.headers.get('content-type')||'').includes('text/event-stream')){const data=await response.json();savedMessage(data.message);if(data.assistantMessage)handle('reply',data);handle(data.replyError?'error':'done',data);return}
  const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';
  while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let split;while((split=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,split);buffer=buffer.slice(split+2);const type=block.split('\n').find(l=>l.startsWith('event:'))?.slice(6).trim();const raw=block.split('\n').filter(l=>l.startsWith('data:')).map(l=>l.slice(5).trimStart()).join('\n');if(type&&raw)handle(type,JSON.parse(raw))}}
  if(!finished)throw Error('Connection interrupted. Reload the conversation to check saved messages.');
 }catch(err){if(err.name!=='AbortError'){if(saved)failReply(err.message,lastSaved);else toast(err.message)}}
 finally{activeChatController=null;button.disabled=false;button.textContent='Send';if(form.isConnected)input.focus()}
}

function operationsPanel({config:c,stats:s,providerConfigured}){return `<section class="panel section"><h2>Chat operations</h2><p class="notice">${providerConfigured?'AI provider configured':'AI provider not configured'}</p><form id="operations-form" class="stack" data-version="${c.version}"><div class="grid-two">${[['chatEnabled','Enable companion chat'],['streamEnabled','Enable streaming'],['memoryEnabled','Enable long-term memory'],['quotaEnabled','Enable free message limit']].map(([k,label])=>`<label class="checkline"><input type="checkbox" name="${k}" ${c[k]?'checked':''}><span>${label}</span></label>`).join('')}<label class="form-field">Free lifetime messages<input name="freeMessageLimit" type="number" min="0" max="1000" value="${c.freeMessageLimit}" required></label><label class="form-field">Chat model<input name="model" value="${esc(c.model)}" required></label><label class="form-field">Maximum output tokens<input name="maxOutputTokens" type="number" min="64" max="4096" value="${c.maxOutputTokens}" required></label><label class="form-field">Recent context messages<input name="contextMessages" type="number" min="2" max="60" value="${c.contextMessages}" required></label></div><label class="form-field">Companion instructions<textarea name="systemPrompt" maxlength="3000">${esc(c.systemPrompt)}</textarea></label><p class="muted">Only completed free replies count. Failures release the reservation. Active members have unlimited text chat. Changes apply to new requests.</p><p class="form-error" role="alert"></p><button class="btn" type="submit">Save operations settings</button></form><div class="stat-grid">${[['Successful replies',s.completed],['Failed replies',s.failed],['Pending replies',s.pending],['Users with memory',s.memoryUsers],['Input tokens',s.inputTokens],['Output tokens',s.outputTokens]].map(([label,n])=>`<div class="stat"><strong>${n}</strong><span>${label}</span></div>`).join('')}</div></section>`}
function spendingPanel(s){return `<section class="panel section"><h2>Monthly token limit</h2><p>Limit token consumption per UTC calendar month. This does not limit subscription or token-pack payments. Blank means no limit; zero blocks spending.</p><p><span>Spent this month</span>: ${s.spent} · <span>Reserved tokens</span>: ${s.held}</p><form id="spending-form" class="stack" data-version="${s.version}"><label class="form-field">Monthly token limit<input name="monthly_token_limit" type="number" min="0" max="1000000" value="${s.monthly_token_limit??''}"></label><p class="form-error" role="alert"></p><button class="btn" type="submit">Save changes</button></form></section>`}
function relationshipCard(r){return `<section class="relationship-preview"><div><strong>Relationship</strong> <span translate="no">Lv.${r.level} · ${esc(r.title)}</span><progress max="1" value="${r.progress}" aria-label="Level progress"></progress></div><button class="btn secondary small" data-action="relationship" data-id="${esc(r.character_id)}">Relationship card</button></section>`}
function updateRelationshipCard(r){const el=$('#relationship-card');if(el?.dataset.character===r.character_id)el.innerHTML=relationshipCard(r)}
function anniversaryRow(a={title:'',date:''}){return `<div class="anniversary-row" data-anniversary-row><label class="form-field">Anniversary title<input name="title" value="${esc(a.title)}" required maxlength="60"></label><label class="form-field">Date<input name="date" type="date" value="${esc(a.date)}" min="1900-01-01" max="2100-12-31" required></label><button type="button" class="btn secondary small" data-action="remove-anniversary">Remove</button></div>`}
function relationshipDetails(r){return `<div class="relationship-heading"><h3 translate="no">Lv.${r.level} · ${esc(r.title)}</h3><p><span>Experience</span>: ${r.xp} · <span>Days together</span>: ${r.daysTogether}</p><progress max="1" value="${r.progress}" aria-label="Level progress"></progress><p>${r.nextLevel?`<span>Experience to next level</span>: ${r.remainingXp}`:'Highest level reached'}</p></div><div class="toolbar">${r.badges.map(b=>`<span class="tag" translate="no">${esc(b.name)}</span>`).join('')}</div><p class="muted"><span>Experience per successful reply</span>: ${r.rules.xpPerReply} · <span>Daily experience cap</span>: ${r.rules.dailyCap} · <span>Earned today</span>: ${r.todayXp}</p>${r.rules.enabled?'':'<p class="notice">Relationship growth is paused</p>'}<p class="tiny muted">Daily limits reset at midnight UTC. Failed or repeated replies earn no experience. Badges are decorative and do not unlock paid features.</p><h3>First meeting</h3><p>${date(r.started)} · <span>Next anniversary</span>: <span translate="no">${r.firstMeeting.nextDate}</span></p><h3>Level milestones</h3>${r.milestones.length?r.milestones.map(m=>`<p>Lv.${m.level} · ${date(m.created)}</p>`).join(''):'<p class="muted">Your next milestone is ahead.</p>'}<h3>Our anniversaries</h3>${r.anniversaries.map(a=>`<p><span translate="no">${esc(a.title)}</span> · <span>Next anniversary</span>: <span translate="no">${a.nextDate}</span> · <span>Days remaining</span>: ${a.daysUntil}</p>`).join('')}<form id="relationship-form" method="post" class="stack" data-character="${esc(r.character_id)}" data-revision="${r.revision}"><div id="anniversary-rows">${r.anniversaries.map(anniversaryRow).join('')}</div><button class="btn secondary small" type="button" data-action="add-anniversary">Add anniversary</button><p class="tiny muted">Up to 10 dates. February 29 is observed on February 28 in non-leap years. Dates use UTC.</p><p class="form-error" role="alert"></p><button class="btn" type="submit">Save anniversaries</button></form>`}
document.addEventListener('submit',async e=>{if(e.target.getAttribute('id')!=='relationship-form')return;e.preventDefault();const f=e.target,b=$('[type=submit]',f);b.disabled=true;try{const anniversaries=$$('[data-anniversary-row]',f).map(row=>({title:$('[name=title]',row).value,date:$('[name=date]',row).value}));const data=await api('/api/characters/'+f.dataset.character+'/relationship',{method:'PATCH',body:{anniversaries,revision:Number(f.dataset.revision)}});updateRelationshipCard(data.relationship);$('#modal').close();toast('Anniversaries saved')}catch(err){$('.form-error',f).textContent=err.message}finally{b.disabled=false}});
function memoryFacts(summary){return summary.split(/\n+/).map(x=>x.trim()).filter(Boolean)}
function characterMemoryCard(data,name){const m=data.memory,active=data.globalEnabled&&data.accountEnabled&&m.enabled;const facts=memoryFacts(m.summary);return `<section class="memory-preview"><div class="row"><div><strong>She remembers you</strong> <span translate="no">· ${esc(name)}</span></div><button class="btn secondary small" data-action="character-memory" data-id="${esc(m.character_id)}">Manage memory</button></div><p class="muted tiny">Only this character can recall these memories.</p>${active?'':'<span class="memory-paused">Memory recall is paused</span>'}<p class="memory-teaser" translate="no">${esc(facts[0]||'')}</p>${facts.length?'':'<p class="muted tiny">No memories yet. Add something you want this character to remember.</p>'}</section>`}
function updateMemoryCard(data){const el=$('#character-memory');if(el&&el.dataset.character===data.memory.character_id)el.innerHTML=characterMemoryCard(data,el.dataset.name)}
function memoryCards(m){return `<div class="memory-card-grid">${memoryFacts(m.summary).map((fact,index)=>`<article class="memory-fact"><p translate="no">${esc(fact)}</p><button type="button" class="btn secondary small" data-action="remove-memory-fact" data-index="${index}">Forget this memory</button></article>`).join('')||'<p class="muted">No memories yet. Add something you want this character to remember.</p>'}</div>`}
function characterMemoryEditor(data,cid){const m=data.memory;return `<p>Only this character can recall these memories.</p><p class="muted">Editing memory does not remove old messages. Recent messages in this conversation can still be used as context.</p>${!data.globalEnabled?'<p class="notice">Memory is disabled by the operator.</p>':''}${!data.accountEnabled?'<p class="notice">Enable character memory in account settings to resume recall.</p>':''}<form id="memory-form" method="post" class="stack" data-character="${esc(cid)}" data-revision="${m.revision}" data-endpoint="/api/characters/${esc(cid)}/memory"><div id="memory-facts">${memoryCards(m)}</div><label class="checkline"><input type="checkbox" name="enabled" ${m.enabled?'checked':''}><span>Allow this character to remember me</span></label><label class="form-field">Remembered details<textarea name="summary" maxlength="2000" rows="5">${esc(m.summary)}</textarea><small>Write one memory per line. Automatic summaries may be imperfect; you can correct them.</small></label><p class="form-error" role="alert"></p><div class="row"><button class="btn" type="submit">Save memory</button><button class="btn secondary" type="button" data-action="clear-memory">Clear memory</button><button class="btn secondary" type="button" data-action="reload-character-memory" data-id="${esc(cid)}">Reload saved memory</button></div></form>`}
function memoryPanel({memory:m,globalEnabled}){return `<section class="panel section"><h2>Character memory settings</h2><p class="muted">Each character has separate memories. Manage them from the memory card in each chat. Old account memory below is archived and is never sent to characters automatically.</p>${globalEnabled?'':'<p class="notice">Memory is disabled by the operator.</p>'}<form id="memory-form" method="post" class="stack" data-revision="${m.revision}" data-endpoint="/api/me/memory"><label class="checkline"><input type="checkbox" name="enabled" ${m.enabled?'checked':''}><span>Enable character memory for my account</span></label><label class="form-field">Archived account memory<textarea name="summary" maxlength="2000" rows="5">${esc(m.summary)}</textarea></label><p class="form-error" role="alert"></p><div class="row"><button class="btn" type="submit">Save memory</button><button class="btn secondary" type="button" data-action="clear-memory">Clear memory</button></div></form></section>`}

function legal(){return `<h1>Terms & privacy</h1><div class="panel stack"><h2>Independent non-commercial implementation</h2><p>This installation is a replica for authorized non-commercial use. It is not the original Candy AI service. Source-site names and media remain the property of their respective owners.</p><h2>Accounts and data</h2><p>On the MVP server, account details, password hashes, sessions, characters, messages, favorites, orders and audit records are stored in a local SQLite database. Passwords are salted and hashed; they are not stored in plain text. On the static preview, demo data is stored in your browser only.</p><h2>AI and billing</h2><p>${modelEnabled?'AI chat uses OpenAI. Recent conversation messages and character metadata are sent to OpenAI to generate replies. API response storage is disabled. Local messages and replies remain in SQLite. Image, voice and video generation are not connected.':'Model APIs are disabled. Messages are stored without an AI response. Demonstration prices are configurable and no payment is collected by this app itself. An external payment provider and verified callback must be configured before taking payments.'}</p><h2>Before public launch</h2><p>The deployment operator must supply their legal entity, contact details, applicable terms, privacy notices, retention policy and payment terms. This page documents the current build; it is not a substitute for those operator-specific documents.</p><h2>Help</h2><p>Account recovery and data deletion requests should be directed to the deployment operator. No external support team is connected.</p></div>`}
async function render(){const rid=++renderId;const [page,arg]=route();let content='';if(page==='admin'){location.replace('/admin/#admin/'+(arg||'overview'));return}try{if(['chat','collection','my-ai','wallet','settings','admin'].includes(page)&&!me){shell('login',auth(false));return}switch(page){case 'home':category='girls';content=home();break;case 'explore':category=['girls','anime','guys'].includes(arg)?arg:'girls';content=`<h1>Explore ${category==='anime'?'Anime Characters':category==='guys'?'AI Guys':'AI Girls'}</h1><p class="subtitle">Find your next companion</p>${toolbar()}${grid(filtered())}`;break;case 'profile':{const c=characters.find(c=>c.id===arg);content=c?profile(c):empty('Character not found','This profile is unavailable.','home','Go home');break}case 'discover':content=`<h1><span class="pink">Discover</span> Candy</h1><p class="subtitle">Characters, previews and new experiences</p><div class="toolbar"><a class="chip active" href="#discover">For you</a><a class="chip" href="#shorts">Video previews</a><a class="chip" href="#explore/anime">Anime</a><a class="chip" href="#create">Create your own</a></div>${videoGrid(D.videos.slice(0,12))}<section class="section"><h2>Featured characters</h2>${grid(characters.filter(c=>!c.owner_id).slice(0,12))}</section>`;break;case 'shorts':content=`<h1>Candy <span class="pink">Shorts</span></h1><p class="subtitle">Public preview clips · stored locally</p>${videoGrid(D.videos)}`;break;case 'collection':content=`<h1>Your collection</h1><p class="subtitle">All your saved companions, in one place</p>${favorites.size?grid(characters.filter(c=>favorites.has(c.id))):empty('Your collection is waiting','Tap the heart on a character to save it here.','explore/girls','Explore characters')}`;break;case 'create':content=create();break;case 'my-ai':{const list=characters.filter(c=>c.owner_id===me.id);content=`<div class="section-heading"><h1>My AI</h1><a class="btn" href="#create">Create Character</a></div>${list.length?grid(list):empty('Create your first companion','Choose a style and make it your own.','create','Create Character')}`;break}case 'tokens':content=await tokenStore();break;case 'premium':content=premium();break;case 'wallet':content=await wallet();break;case 'chat':content=await chat(arg);break;case 'settings':content=await settings();break;case 'admin':content=await admin(arg);break;case 'forgot':content=recovery();break;case 'reset':content=recovery(arg);break;case 'login':case 'register':content=auth(page==='register');break;case 'legal':content=legal();break;case 'help':content=`<h1>Help center</h1>${faq()}<div class="panel section"><h2>Account support</h2><p class="muted">Contact the operator of this installation for account recovery, data export or deletion requests. Original-site customer support is not connected to this installation.</p></div>`;break;case 'affiliate':content=`<h1>Candy AI <span class="pink">Affiliate</span></h1><div class="panel"><h2>Partner program</h2><p class="muted">The source site’s affiliate page is preserved in the static snapshots. This MVP does not run an affiliate program or pay commissions.</p><a class="btn secondary" href="#home">Explore the platform</a></div>`;break;case 'generate':content=`<h1>Create an image or video</h1><div class="panel stack"><label class="form-field">Describe your scene<textarea id="generation-prompt" placeholder="Describe an environment, outfit or portrait"></textarea></label><div class="notice">Model API integration is intentionally disabled. No generation requests are submitted and no tokens are deducted.</div><button class="btn" disabled>Generation unavailable</button></div>`;break;case 'library':content=`<h1>Local media library</h1><p class="subtitle">${D.videos.length} public preview videos · assets served locally</p><div class="toolbar"><a class="chip active" href="#library">Videos</a><a class="chip" href="#explore/girls">Character portraits</a></div>${videoGrid(D.videos)}`;break;default:content=empty('Page not found','Choose a page from the sidebar.','home','Go home')}
 if(rid!==renderId)return;shell(page,content);if(page==='chat'){const box=$('#messages');if(box)box.scrollTop=box.scrollHeight}window.scrollTo(0,0);
 }catch(e){if(rid===renderId)shell(page,`<div class="error-page"><h1>Unable to load this page</h1><p class="muted">${esc(e.message)}</p><button class="btn" data-action="retry">Try again</button></div>`)}}
function wireMemory(){const f=$('#memory-form');if(!f||f.dataset.bound)return;f.dataset.bound='1';
 $('#memory-form textarea')?.addEventListener('input',()=>{$$('[data-action=remove-memory-fact]').forEach(b=>b.disabled=true)});
 $('#memory-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;try{const result=await api(f.dataset.endpoint||'/api/me/memory',{method:'PATCH',body:{summary:f.elements.summary.value,enabled:f.elements.enabled.checked,revision:Number(f.dataset.revision)}});f.dataset.revision=result.memory.revision;f.elements.summary.value=result.memory.summary;$('.form-error',f).textContent='';if(f.dataset.character){$('#memory-facts',f).innerHTML=memoryCards(result.memory);updateMemoryCard(result)}toast('Memory saved')}catch(err){$('.form-error',f).textContent=err.message}});
}
function wire(){
 wireMemory();
 $('#spending-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;try{const raw=f.elements.monthly_token_limit.value;await api('/api/me/settings',{method:'PATCH',body:{monthly_token_limit:raw===''?null:Number(raw),version:Number(f.dataset.version)}});await render();toast('Spending limit saved')}catch(err){$('.form-error',f).textContent=err.message}});

 $('#operations-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=$('button[type=submit]',f);b.disabled=true;try{const body=Object.fromEntries(new FormData(f));for(const k of ['chatEnabled','streamEnabled','memoryEnabled','quotaEnabled'])body[k]=f.elements[k].checked;for(const k of ['freeMessageLimit','maxOutputTokens','contextMessages'])body[k]=Number(body[k]);body.version=Number(f.dataset.version);await api('/api/admin/config',{method:'PUT',body});await render();toast('Operations settings saved')}catch(err){$('.form-error',f).textContent=err.message}finally{b.disabled=false}});

 $('#character-details')?.addEventListener('submit',e=>{e.preventDefault();$('[data-action=wizard-next]')?.click()});
 if(route()[0]==='login'){const note=$('.auth>.muted');if(note)note.innerHTML='<a class="pink" href="#forgot">Forgot your password?</a>'}
 $('#recovery-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=$('button',form);button.disabled=true;try{const payload=Object.fromEntries(new FormData(form));if(form.dataset.token)payload.token=form.dataset.token;const result=await api(form.dataset.token?'/api/auth/reset':'/api/auth/forgot',{method:'POST',body:payload});if(form.dataset.token){me=null;csrf=null;go('login');toast('Password reset. Please sign in with your new password.')}else{toast(result.notice);form.reset()}}catch(err){$('.form-error',form).textContent=err.message}finally{button.disabled=false}});
 $$('.card').forEach(c=>{const v=$('video',c);if(v){c.addEventListener('mouseenter',()=>v.play().catch(()=>{}));c.addEventListener('mouseleave',()=>v.pause())}});
 $('#character-search')?.addEventListener('input',e=>{search=e.target.value;const gridEl=$('#character-grid');if(gridEl){gridEl.innerHTML=filtered().map(card).join('');if(!filtered().length)gridEl.innerHTML='<p class="muted">No matching characters.</p>'}});
 $('#header-search')?.addEventListener('submit',e=>{e.preventDefault();search=new FormData(e.currentTarget).get('query');go('explore/'+category)});
 $('#auth-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=$('button[type=submit]',form);button.disabled=true;try{const b=Object.fromEntries(new FormData(form));b.adult=!!b.adult;const register=form.dataset.register==='true';await api('/api/auth/'+(register?'register':'login'),{method:'POST',body:b});await refresh();go('home');toast(STATIC?'Offline demo entered':'Signed in successfully')}catch(err){$('.form-error',form).textContent=err.message}finally{button.disabled=false}});
 $('#message-form')?.addEventListener('submit',sendChat);
 $('#profile-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;try{const name=new FormData(form).get('name');if(STATIC){offline.user.name=name;persist()}else await api('/api/me',{method:'PATCH',body:{name}});await refresh();toast('Profile updated')}catch(err){$('.form-error',form).textContent=err.message}});
 $('#password-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;try{await api('/api/auth/password',{method:'POST',body:Object.fromEntries(new FormData(form))});form.reset();toast('Password changed; other sessions have been signed out')}catch(err){$('.form-error',form).textContent=err.message}});
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();e.stopPropagation();const action=b.dataset.action,cid=b.dataset.id;try{
 if(action.startsWith('manage-')){await adminUI.click(action,b);return}
 if(action==='retry-reply'){const form=$('#message-form');form.dataset.retryMessageId=b.dataset.messageId;form.dataset.requestContent=b.dataset.content;form.elements.content.value=b.dataset.content;form.requestSubmit();return}
 if(action==='relationship'){const d=await api('/api/characters/'+cid+'/relationship');modal('Relationship card',relationshipDetails(d.relationship));return}
 if(action==='add-anniversary'){const rows=$('#anniversary-rows');if($$('[data-anniversary-row]',rows).length>=10){toast('At most 10 anniversaries');return}rows.insertAdjacentHTML('beforeend',anniversaryRow());return}
 if(action==='remove-anniversary'){b.closest('[data-anniversary-row]').remove();return}
 if(action==='character-memory'||action==='reload-character-memory'){const data=await api('/api/characters/'+cid+'/memory');if($('#modal').open)$('#modal').close();modal('She remembers you',characterMemoryEditor(data,cid));return}
 if(action==='remove-memory-fact'){const f=$('#memory-form'),facts=memoryFacts(f.elements.summary.value);facts.splice(Number(b.dataset.index),1);f.elements.summary.value=facts.join('\n');f.requestSubmit();return}
 if(action==='clear-memory'){const f=$('#memory-form');f.elements.summary.value='';f.requestSubmit();return}
 if(action==='menu'){document.body.classList.toggle(innerWidth<=900?'mobile-menu':'collapsed');return}
 if(action==='close-modal'){$('#modal').close();return}
 if(action==='retry'){await render();return}
 if(action.startsWith('hero-')){heroIndex=action==='hero-dot'?Number(b.dataset.index):(heroIndex+(action==='hero-next'?1:-1)+D.slides.length)%D.slides.length;$('.hero').outerHTML=hero();return}
 if(action==='sort'){characters.sort((a,b)=>a.name.localeCompare(b.name));await render();return}
 if(action==='report-message'){if(!needUser())return;modal('Report content',`<p>Only the reported content will be shared with reviewers, not your full conversation.</p><label class="form-field">Reason<textarea id="report-reason" maxlength="1000"></textarea></label><button class="btn" data-action="submit-report" data-type="${b.dataset.type==='character'?'character':'message'}" data-id="${esc(cid)}" data-key="${key()}">Submit report</button>`);return}
 if(action==='submit-report'){await api('/api/reports',{method:'POST',headers:{'Idempotency-Key':b.dataset.key},body:{target_type:b.dataset.type||'message',target_id:cid,reason:$('#report-reason').value}});$('#modal').close();toast('Report submitted');return}
 if(action==='delete-account'){modal('Delete account',`<p>This permanently deletes your account, conversations, memories, characters and local order records. Any unused balance is lost. This does not issue a refund. Export your data first.</p><label class="form-field">Current password<input id="delete-password" type="password" autocomplete="current-password"></label><label class="checkline"><input id="delete-confirm" type="checkbox"><span>I understand this cannot be undone</span></label><button class="btn danger" data-action="confirm-delete-account">Delete account</button>`);return}
 if(action==='confirm-delete-account'){await api('/api/me',{method:'DELETE',body:{password:$('#delete-password').value,confirm:$('#delete-confirm').checked}});$('#modal').close();me=null;csrf=null;await refresh();go('register');toast('Account deleted');return}
 if(action==='favorite'){if(!needUser())return;const saved=favorites.has(cid);await api('/api/favorites/'+cid,{method:saved?'DELETE':'PUT',body:{}});if(saved)favorites.delete(cid);else favorites.add(cid);b.textContent=saved?'♡':'♥';toast(saved?'Removed from collection':'Saved to collection');if(route()[0]==='collection')await render();return}
 if(action==='start-chat'){if(!needUser())return;const result=await api('/api/conversations',{method:'POST',body:{characterId:cid}});go('chat/'+result.conversation.id);return}
 if(action==='choose-style'){draft.style=b.dataset.value;const c=characters.find(c=>c.style===draft.style&&c.gender===draft.gender)||characters.find(c=>c.style===draft.style);draft.image=c?.image||draft.image;await render();return}
 if(action==='choose-gender'){draft.gender=b.dataset.value;const c=characters.find(c=>!c.owner_id&&c.style===draft.style&&c.gender===draft.gender);draft.image=c?.image||draft.image;await render();return}
 if(action==='choose-image'){draft.image=b.dataset.value;$$('.portrait-options button').forEach(x=>x.classList.toggle('selected',x===b));return}
 if(action==='wizard-back'){if(draft.step===1)draft.age=Number($('#draft-age').value);if(draft.step===2){draft.name=$('#draft-name').value;draft.description=$('#draft-description').value;draft.personality=$('#draft-personality').value}draft.step--;await render();return}
 if(action==='wizard-next'){if(draft.step===1){draft.age=Number($('#draft-age').value);if(!Number.isInteger(draft.age)||draft.age<18||draft.age>100)throw Error('Choose an age between 18 and 100')}if(draft.step===2){draft.name=$('#draft-name').value.trim();draft.description=$('#draft-description').value.trim();draft.personality=$('#draft-personality').value;if(!draft.name)throw Error('Give your character a name')}draft.step++;await render();return}
 if(action==='save-character'){if(!needUser())return;b.disabled=true;const result=await api('/api/characters',{method:'POST',body:draft});await refresh();draft.step=0;go('profile/'+result.character.id);toast('Your character has been created');return}
 if(action==='delete-character'){modal('Delete character?',`<p>This will also delete the character’s conversations. This cannot be undone.</p><button class="btn danger" data-action="confirm-delete-character" data-id="${cid}">Delete character</button>`);return}
 if(action==='confirm-delete-character'){await api('/api/characters/'+cid,{method:'DELETE',body:{}});$('#modal').close();await refresh();go('my-ai');return}
 if(action==='delete-chat'){modal('Delete this conversation?',`<p>All messages in this conversation will be deleted.</p><button class="btn danger" data-action="confirm-delete-chat" data-id="${cid}">Delete conversation</button>`);return}
 if(action==='confirm-delete-chat'){await api('/api/conversations/'+cid,{method:'DELETE',body:{}});$('#modal').close();go('chat');return}
 if(action==='checkout'){if(!needUser())return;const p=plans.find(p=>p.id===b.dataset.plan);modal('Review your order',`<p><span translate="no">${esc(p.name)}</span> · ${money(p.amount,p.currency)} total · ${p.tokens} tokens</p><div class="notice">This creates an unpaid order. No card details are collected and no payment is taken here.</div><button class="btn wide" data-action="create-order" data-plan="${p.id}" data-version="${p.version||1}" data-key="${key()}">Create order</button>`);return}
 if(action==='create-order'){b.disabled=true;const result=await api('/api/orders',{method:'POST',headers:{'Idempotency-Key':b.dataset.key},body:{plan:b.dataset.plan,planVersion:Number(b.dataset.version)}});$('#modal').close();go('wallet');toast(result.notice||'Order created');if(result.checkoutUrl)modal('Continue to payment',`<p>Your order is pending. Continue to the configured payment provider.</p><a class="btn" href="${esc(result.checkoutUrl)}" rel="noopener noreferrer">Open checkout</a>`);return}
 if(action==='cancel-order'){await api('/api/orders/'+cid+'/cancel',{method:'POST',body:{}});await render();return}
 if(action==='cancel-subscription'){await api('/api/subscription/cancel',{method:'POST',body:{}});await render();toast('Renewal disabled');return}
 if(action==='logout'){await api('/api/auth/logout',{method:'POST',body:{}});await refresh();go('login');return}
 if(action==='export'){const data=await api('/api/me/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='my-companion-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}
 if(action==='settle-order'){modal('Confirm external settlement',`<p>Only confirm after payment has been verified outside this application. This action grants membership and tokens once.</p><label class="form-field">Receipt or reason<input id="settle-reason" maxlength="200" required></label><button class="btn" data-action="confirm-settle" data-id="${cid}">Confirm settlement</button>`);return}
 if(action==='confirm-settle'){const reason=$('#settle-reason').value.trim();if(!reason)throw Error('Enter a receipt or verification reason');await api('/api/admin/orders/'+cid+'/settle',{method:'POST',body:{reason}});$('#modal').close();await render();return}
 if(action==='adjust-credits'){modal('Adjust token balance',`<div class="stack"><label class="form-field">Adjustment<input id="credit-delta" type="number" value="100"></label><label class="form-field">Reason<input id="credit-reason" maxlength="200"></label><button class="btn" data-action="confirm-credit" data-id="${cid}" data-key="${key()}">Record adjustment</button></div>`);return}
 if(action==='confirm-credit'){await api('/api/admin/credits',{method:'POST',headers:{'Idempotency-Key':b.dataset.key},body:{userId:cid,delta:Number($('#credit-delta').value),reason:$('#credit-reason').value}});$('#modal').close();await render();toast('Adjustment recorded');return}
}catch(err){toast(err.message);b.disabled=false}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
window.addEventListener('hashchange',()=>{activeChatController?.abort();render()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('mobile-menu')});
(async()=>{try{await refresh();await render()}catch(e){$('#app').innerHTML=`<div class="error-page"><h1>Unable to connect</h1><p>${esc(e.message)}</p><p>Start the MVP server with <code>npm start</code>, or open the separate offline static version.</p></div>`}})();
})();
